        ok: true, 
        user: {
          id: user.id,
          email: user.email,
          firstName: user.firstName,
          lastName: user.lastName,
          userType: user.role === "owner" ? "owner" : "customer"
        },
        redirectTo: user.role === "owner" ? "/owner/dashboard" : "/home"
