  function mockPaymentSuccess(amount: number, currency = 'EUR') {
    return {
      ok: true,
      mode: 'review',
      payment: {
        status: 'succeeded',
        provider: 'mock',
        amount,
        currency,
        id: 'pm_mock_' + Date.now()
      }
    };
