                        <li>✓ Assicurazione completa inclusa</li>
                        <li>✓ Dashboard dedicata per gestire tutto</li>
                      </ul>
                    </CardContent>
                  </Card>
                </div>
              )}

              {/* Navigation Buttons */}
              <div className="flex justify-between pt-6">
                <Button
                  type="button"
                  variant="outline"
                  onClick={prevStep}
                  disabled={currentStep === 1}
                >
                  Indietro
