                    />
                  </svg>
                </div>

                {/* Boat markers */}
                {boatsWithLocation.slice(0, 8).map((boat, index) => {
                  const x = 50 + (index % 4) * 80;
                  const y = 50 + Math.floor(index / 4) * 100;

                  return (
