  const [isOpen, setIsOpen] = useState(false);

  return (
    <>
      <Button
        onClick={() => setIsOpen(true)}
        variant="outline"
        className={`border-ocean-blue text-ocean-blue hover:bg-ocean-blue hover:text-white ${className}`}
