        <MessageCircle className="h-4 w-4 mr-2" />
        Messaggio
      </Button>

      <ChatWindow
        bookingId={bookingId}
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
      />
    </>
  );
}

