import { Anchor, Users, Star, TrendingUp } from "lucide-react";

export function QuickStatsCard() {
  const stats = [
    {
      icon: Anchor,
      label: "Barche disponibili",
      value: "500+",
      trend: "+12% questo mese",
      color: "text-blue-600"
