import { useLocation } from "wouter";

interface StructuredDataProps {
  type: 'homepage' | 'esperienze' | 'charter' | 'ormeggio' | 'boat-details' | 'service-page';
  data?: any;
}

export function StructuredData({ type, data }: StructuredDataProps) {
