          <p className="text-gray-600 mb-6">Non è stato possibile inizializzare il pagamento.</p>
          <Button asChild>
            <Link href="/esperienze">Torna alle esperienze</Link>
          </Button>
        </div>
        <Footer />
      </div>
    );
  }

  return (
