                      {form.formState.errors.boatYear && (
                        <p className="text-red-500 text-sm mt-1">{form.formState.errors.boatYear.message}</p>
                      )}
                    </div>

                    <div>
                      <Label htmlFor="boatLength">Lunghezza (m) *</Label>
                      <Input
                        id="boatLength"
                        type="number"
                        step="0.1"
                        {...form.register("boatLength", { valueAsNumber: true })}
