                <CardTitle className="text-sm font-medium">Regole Attive</CardTitle>
                <Tag className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">
                  {bookingRules.filter((rule: any) => rule.active).length}
