                            </li>
                            <li className="flex items-center gap-2">
                              <img src={seabooLogo} alt="SeaBoo" className="h-3 w-3 object-contain" />
                              VHF nautico
                            </li>
                            <li className="flex items-center gap-2">
                              <img src={seabooLogo} alt="SeaBoo" className="h-3 w-3 object-contain" />
                              Kit di primo soccorso
                            </li>
                            <li className="flex items-center gap-2">
                              <img src={seabooLogo} alt="SeaBoo" className="h-3 w-3 object-contain" />
                              Ancora di emergenza
                            </li>
                          </ul>
                        </CardContent>
                      </Card>

                      <Card>
                        <CardHeader>
                          <CardTitle className="text-base">Previsioni Brevi</CardTitle>
                        </CardHeader>
                        <CardContent>
                          <div className="space-y-2 text-sm">
                            {weatherData.forecast.slice(0, 3).map((forecast, index) => (
                              <div key={index} className="flex justify-between">
                                <span>{formatTime(forecast.time)}</span>
                                <span>{forecast.waves}m • {forecast.windSpeed}kn</span>
                              </div>
                            ))}
                          </div>
                        </CardContent>
                      </Card>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </>
          )}
        </TabsContent>

        {/* Partners Tab */}
        <TabsContent value="partners" className="space-y-6">
          <PartnersSection />
        </TabsContent>
      </Tabs>
      </div>
    </div>
  );
}

