import { useState } from 'react';

interface Port {
  id: string;
  name: string;
  lat: number;
  lng: number;
  boats: number;
  priceRange: string;
  description: string;
  icon: string;
}

const lazioCoastPorts: Port[] = [
  {
    id: 'civitavecchia',
