          </View>
          <Text style={styles.statLabel}>Valutazione</Text>
        </View>
      </View>
    </View>
  );

  const renderMenuItem = (item, sectionIndex, itemIndex) => (
    <TouchableOpacity 
      key={`${sectionIndex}-${itemIndex}`}
      style={styles.menuItem}
      onPress={() => handleMenuPress(item.action)}
    >
