        </View>
      )}

      {/* App Info */}
      <View style={styles.appInfo}>
        <Text style={styles.appInfoText}>SeaBoo v1.0.0</Text>
        <Text style={styles.appInfoText}>© 2025 SeaBoo. Tutti i diritti riservati.</Text>
      </View>
    </ScrollView>
  );
};

