      // Filtra per l'utente corrente se non è admin
      const filteredDocuments = req.user.role === 'admin' 
        ? expiringDocuments 
        : expiringDocuments.filter(doc => doc.userId === req.user.id);

      res.json(filteredDocuments);

    } catch (error) {
