});

const bulkAvailabilitySchema = z.object({
  startDate: z.string(),
  endDate: z.string(),
  seasonType: z.enum(['high', 'medium', 'low']),
  priceMultiplier: z.number().min(0.1).max(10),
  available: z.boolean(),
  blockReason: z.string().optional(),
  notes: z.string().optional()
});

