}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
    /* Fix per mobile: rimuovi scroll orizzontale */
    overflow-x: hidden;
  }

  /* Fix specifico per mobile: impedisci scroll orizzontale */
  @media (max-width: 768px) {
    html, body {
      overflow-x: hidden;
      width: 100%;
      max-width: 100vw;
    }

    /* Assicura che tutti i contenitori rispettino i limiti */
    * {
      max-width: 100%;
      box-sizing: border-box;
    }

    /* Fix per elementi che potrebbero causare overflow */
    .container, 
    .max-w-7xl,
    .max-w-6xl,
    .max-w-4xl {
      max-width: 100vw !important;
      overflow-x: visible;
    }

