    "seller": {
      "@type": "Organization",
      "name": "SeaBoo"
    }
  },
  "image": boat.images?.[0] || "/attached_assets/default-boat.jpg",
  "additionalProperty": [
    {
      "@type": "PropertyValue",
      "name": "Boat Type",
      "value": boat.type
    },
    {
      "@type": "PropertyValue", 
      "name": "Capacity",
      "value": `${boat.capacity} persone`
    },
    {
      "@type": "PropertyValue",
      "name": "Location",
      "value": boat.port
    },
    {
      "@type": "PropertyValue",
      "name": "Length",
      "value": `${boat.length || 'N/A'} metri`
    }
  ],
  "aggregateRating": boat.rating ? {
    "@type": "AggregateRating",
    "ratingValue": boat.rating,
    "reviewCount": boat.reviewCount || 1,
    "bestRating": 5,
    "worstRating": 1
  } : undefined
});

// Utility to clean and optimize URLs for SEO
export const generateSEOUrl = (title: string, id?: number): string => {
  const cleanTitle = title
    .toLowerCase()
    .replace(/[àáâãäå]/g, 'a')
    .replace(/[èéêë]/g, 'e')
    .replace(/[ìíîï]/g, 'i')
    .replace(/[òóôõö]/g, 'o')
    .replace(/[ùúûü]/g, 'u')
    .replace(/[ý]/g, 'y')
    .replace(/[ñ]/g, 'n')
    .replace(/[ç]/g, 'c')
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim()
    .replace(/^-|-$/g, '');

  return id ? `${cleanTitle}-${id}` : cleanTitle;
};

