                {data.filter(b => b.occupancyRate < 60).length}
              </div>
              <div className="text-sm text-orange-700">Da Migliorare</div>
              <div className="text-xs text-orange-600 mt-1">&lt;60% occupazione</div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

