import { Anchor, ArrowLeft } from "lucide-react";
import seabooLogo from "@assets/WhatsApp Image 2025-08-19 at 12.38.33_1757318764148.jpeg";
import { useToast } from "@/hooks/use-toast";

const loginSchema = z.object({
  email: z.string().email("Email non valida"),
  password: z.string().min(1, "Password richiesta"),
});

const registerSchema = insertUserSchema.extend({
  confirmPassword: z.string(),
  acceptTerms: z.boolean(),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Le password non coincidono",
  path: ["confirmPassword"],
}).refine((data) => data.acceptTerms, {
  message: "Devi accettare i termini e condizioni",
  path: ["acceptTerms"],
});

type LoginData = z.infer<typeof loginSchema>;
type RegisterData = z.infer<typeof registerSchema>;

export default function AuthPage() {
  const { user, loginMutation, registerMutation, appleLoginMutation } = useAuth();
  const [location, setLocation] = useLocation();
  const { toast } = useToast();

  // Check URL parameters for initial tab
  const getInitialTab = () => {
    const urlParams = new URLSearchParams(window.location.search);
    const tabParam = urlParams.get('tab');
    return tabParam === 'register' ? 'register' : 'login';
  };

  const [activeTab, setActiveTab] = useState(getInitialTab());

  const loginForm = useForm<LoginData>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
    },
  });

  // Extract pre-filled data from URL parameters for registration
  const getPreFilledRegisterValues = () => {
    const urlParams = new URLSearchParams(window.location.search);
    // Get role from URL parameter, defaulting to "customer"
    const roleParam = urlParams.get('role');
    const role = (roleParam === 'owner') ? "owner" as const : "user" as const;

    return {
      username: "",
      email: urlParams.get('email') || "",
      password: "",
      confirmPassword: "",
      role: role,
      firstName: urlParams.get('firstName') || "",
      lastName: urlParams.get('lastName') || "",
      phone: urlParams.get('phone') || "",
      businessName: "",
      businessType: "",
      vatNumber: "",
      website: "",
      instagram: "",
      acceptTerms: false,
    };
  };

  const registerForm = useForm<RegisterData>({
    resolver: zodResolver(registerSchema),
    defaultValues: getPreFilledRegisterValues(),
  });

  // Redirect if already logged in
  if (user) {
    return <Redirect to="/" />;
  }

  const onLogin = (data: LoginData) => {
    loginMutation.mutate(data);
  };

  const onRegister = (data: RegisterData) => {
    const { confirmPassword, acceptTerms, ...registerData } = data;
    registerMutation.mutate(registerData);
  };

  const handleAppleSignIn = async () => {
    try {
      // Check if we're in review mode or development mode
      const isReviewMode = import.meta.env.VITE_REVIEW_MODE === 'true' || 
                          window.location.hostname.includes('replit.app');

      if (isReviewMode) {
        // For Apple Review or development testing: simulate Apple ID token
        const mockAppleData = {
          id_token: 'mock_apple_id_token_' + Date.now(),
          user_info: {
            name: {
              firstName: 'Apple',
              lastName: 'User'
            },
            email: 'apple.user@icloud.com'
          }
        };

        console.log('Using mock Apple Sign In for review/development mode');
        appleLoginMutation.mutate(mockAppleData);
      } else {
        // Real Apple Sign In for production
        if (window.AppleID) {
          const response = await window.AppleID.auth.signIn();

          appleLoginMutation.mutate({
            id_token: response.authorization.id_token,
            user_info: response.user
          });
        } else {
          toast({
            title: "Apple Sign In non disponibile",
            description: "L'SDK Apple non è caricato",
            variant: "destructive",
          });
        }
      }
    } catch (error) {
      console.error('Apple Sign In error:', error);
      toast({
        title: "Errore Apple Sign In",
        description: "Impossibile completare l'accesso con Apple",
        variant: "destructive",
      });
    }
  };

  return (
    <div className="min-h-screen flex">
      {/* Left side - Form */}
      <div className="flex-1 bg-white overflow-y-auto">
        <div className="p-8 min-h-full">
          {/* Back to Home Button */}
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={() => setLocation("/")}
              className="text-gray-600 hover:text-gray-900"
            >
              <ArrowLeft className="mr-2 h-4 w-4" />
              Torna alla home
            </Button>
          </div>

          <div className="w-full max-w-md mx-auto min-h-screen flex flex-col justify-center py-12">
            <div className="text-center mb-8">
            <div className="flex items-center justify-center mb-4">
              <Anchor className="h-8 w-8 text-ocean-blue mr-2" />
              <h1 className="text-3xl font-bold text-ocean-blue">SeaBoo</h1>
            </div>
            <p className="text-gray-600">Naviga verso l'avventura</p>
          </div>

          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full grid-cols-2 bg-gray-100 p-1 rounded-lg">
              <TabsTrigger 
                value="login" 
                className="data-[state=active]:bg-ocean-blue data-[state=active]:text-white data-[state=active]:shadow-sm font-medium transition-all duration-200"
              >
                Accedi
              </TabsTrigger>
              <TabsTrigger 
                value="register"
                className="data-[state=active]:bg-ocean-blue data-[state=active]:text-white data-[state=active]:shadow-sm font-medium transition-all duration-200"
              >
                Registrati
              </TabsTrigger>
            </TabsList>

            <TabsContent value="login">
              <Card>
                <CardHeader>
                  <CardTitle>Accedi al tuo account</CardTitle>
                  <CardDescription>
                    Inserisci le tue credenziali per accedere
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <form onSubmit={loginForm.handleSubmit(onLogin)} className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="email">Email</Label>
                      <Input
                        id="email"
