SeaBoo-iOS-DEFINITIVO-FINALE-OLD/client/.content:
import React from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Cloud, 
  Wind, 
  Thermometer, 
  Eye,
  ArrowRight,
  MapPin
} from 'lucide-react';
import seabooLogo from "@assets/WhatsApp Image 2025-08-19 at 12.38.33_1757318764148.jpeg";
import { useQuery } from '@tanstack/react-query';
import { Link } from 'wouter';

interface WeatherData {
  location: string;
  temperature: number;
  description: string;
  windSpeed: number;
  windDirection: number;
  humidity: number;
  pressure: number;
  visibility: number;
  waves: {
    height: number;
    direction: number;
    period: number;
  };
}

export function WeatherWidget() {
  const { data: weatherData, isLoading } = useQuery<WeatherData>({
    queryKey: ['weather-widget', 'Roma'],
    queryFn: async () => {
      const response = await fetch('/api/external/weather?location=Roma');
      if (!response.ok) throw new Error('Failed to fetch weather');
      return response.json();
    },
    refetchInterval: 300000 // Refresh every 5 minutes
  });

  const getWaveCondition = (height: number) => {
    if (height <= 0.5) return { text: 'Calmo', color: 'bg-green-500' };
    if (height <= 1.0) return { text: 'Leggero', color: 'bg-yellow-500' };
    if (height <= 2.0) return { text: 'Moderato', color: 'bg-orange-500' };
    return { text: 'Mosso', color: 'bg-red-500' };
  };

  const getWindDirection = (degrees: number) => {
    const directions = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
    return directions[Math.round(degrees / 22.5) % 16];
  };

  if (isLoading) {
    return (
      <Card className="bg-gradient-to-r from-blue-50 to-cyan-50 border-blue-200">
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Cloud className="h-8 w-8 animate-pulse text-blue-500" />
            <span className="ml-2 text-blue-700">Caricamento meteo...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!weatherData) {
    return null;
  }

  const waveCondition = getWaveCondition(weatherData.waves.height);

  return (
    <Card className="bg-gradient-to-r from-blue-50 to-cyan-50 border-blue-200 hover:shadow-lg transition-shadow">
      <CardContent className="p-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Cloud className="h-6 w-6 text-blue-600" />
            <h3 className="text-lg font-semibold text-blue-900">Condizioni Marine</h3>
          </div>
          <div className="flex items-center gap-1 text-sm text-blue-700">
            <MapPin className="h-4 w-4" />
            <span>{weatherData.location}</span>
          </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          <div className="text-center">
            <Thermometer className="h-6 w-6 mx-auto mb-1 text-orange-500" />
            <div className="text-xl font-bold text-gray-900">{weatherData.temperature}°C</div>
            <div className="text-xs text-gray-600 capitalize">{weatherData.description}</div>
          </div>

          <div className="text-center">
            <Wind className="h-6 w-6 mx-auto mb-1 text-blue-500" />
            <div className="text-xl font-bold text-gray-900">{weatherData.windSpeed} kn</div>
            <div className="text-xs text-gray-600">
              {getWindDirection(weatherData.windDirection)}
            </div>
          </div>

          <div className="text-center">
            <img src={seabooLogo} alt="SeaBoo" className="h-6 w-6 mx-auto mb-1 object-contain" />
            <div className="text-xl font-bold text-gray-900">{weatherData.waves.height} m</div>
            <Badge className={`${waveCondition.color} text-white text-xs`}>
              {waveCondition.text}
            </Badge>
          </div>

          <div className="text-center">
            <Eye className="h-6 w-6 mx-auto mb-1 text-purple-500" />
            <div className="text-xl font-bold text-gray-900">{weatherData.visibility} km</div>
            <div className="text-xs text-gray-600">Visibilità</div>
          </div>
        </div>

        <div className="flex items-center justify-between">
          <div className="text-sm text-gray-700">
            <span className="font-medium">Navigazione:</span>
            <span className="ml-1">
              {weatherData.waves.height <= 0.5 && weatherData.windSpeed <= 10 
                ? 'Condizioni ottime' 
                : weatherData.waves.height <= 1.5 && weatherData.windSpeed <= 20
                ? 'Condizioni moderate'
                : 'Attenzione richiesta'
              }
            </span>
          </div>

          <Button variant="outline" size="sm" asChild className="text-blue-700 hover:text-blue-900">
            <Link href="/external-services">
              Dettagli completi
              <ArrowRight className="h-4 w-4 ml-1" />
            </Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

SeaBoo-iOS-Ready-3-MOBILE/server/routes/.content:
import { Router } from "express";
import OpenAI from "openai";

const router = Router();

// Initialize OpenAI with error handling
let openai: OpenAI | null = null;

try {
  if (process.env.OPENAI_API_KEY) {
    openai = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY,
    });
  }
} catch (error) {
  console.warn("OpenAI not initialized - API key may be missing");
}

// AI Chat endpoint
router.post("/chat", async (req, res) => {
  try {
    const { message, context } = req.body;

    if (!message || typeof message !== 'string') {
      return res.status(400).json({ 
        error: "Message is required and must be a string" 
      });
    }

    // Check if OpenAI is available
    if (!openai) {
      return res.status(503).json({
        error: "AI service temporarily unavailable",
        fallbackMessage: "Mi dispiace, il servizio di assistenza AI non è al momento disponibile. Puoi contattarci tramite email per ricevere supporto immediato."
      });
    }

    // Create system prompt for SeaBoo maritime assistant
    const systemPrompt = `Sei l'assistente AI di SeaBoo, una piattaforma italiana per il noleggio di barche nel Lazio. 

    Le tue competenze includono:
    - Informazioni su barche disponibili (yacht, gommoni, catamarani, barche a vela, jet ski, charter, houseboat)
    - Consigli su porti e marine nel Lazio (Civitavecchia, Gaeta, Ponza, Terracina, Anzio, Formia, Nettuno)
    - Condizioni meteo marine e raccomandazioni di sicurezza
    - Prezzi carburante nautico e servizi portuali
    - Assistenza per prenotazioni e noleggi
    - Informazioni su patenti nautiche e requisiti
    - Consigli per itinerari e destinazioni marine nel Lazio

    Rispondi sempre in italiano, in modo cordiale e professionale. Se non conosci una informazione specifica, suggerisci di contattare il servizio clienti o fornisci informazioni generali utili.

    Non inventare prezzi specifici o disponibilità esatte - suggerisci di consultare la piattaforma per informazioni aggiornate.`;

    // the newest OpenAI model is "gpt-4o" which was released May 13, 2024. do not change this unless explicitly requested by the user
    const completion = await openai.chat.completions.create({
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content: systemPrompt
        },
        {
          role: "user", 
          content: message
        }
      ],
      max_tokens: 500,
      temperature: 0.7,
    });

    const response = completion.choices[0]?.message?.content;

    if (!response) {
      return res.status(500).json({
        error: "No response from AI service",
        fallbackMessage: "Mi dispiace, non sono riuscito a elaborare la tua richiesta. Prova a riformulare la domanda."
      });
    }

    res.json({ 
      response,
      model: "gpt-4o",
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error("AI Chat error:", error);

    // Handle specific OpenAI errors
    if (error instanceof Error && error.message.includes('API key')) {
      return res.status(401).json({
        error: "API key invalid",
        fallbackMessage: "Il servizio AI necessita di configurazione. Contatta il supporto tecnico."
      });
    }

    if (error instanceof Error && error.message.includes('quota')) {
      return res.status(429).json({
        error: "API quota exceeded", 
        fallbackMessage: "Il servizio AI ha raggiunto il limite di utilizzo. Riprova più tardi o contatta il supporto."
      });
    }

    res.status(500).json({
      error: "Internal server error",
      fallbackMessage: "Mi dispiace, c'è stato un errore tecnico. Il nostro team è stato avvisato. Puoi contattarci via email per assistenza immediata."
    });
  }
});

// Health check endpoint for AI service
router.get("/status", (req, res) => {
  res.json({
    aiServiceAvailable: !!openai,
    hasApiKey: !!process.env.OPENAI_API_KEY,
    timestamp: new Date().toISOString()
  });
});

export default router;

SeaBoo-Mobile-COMPLETA/shared/schema.ts.content:
import { sql } from 'drizzle-orm';
import {
  index,
  jsonb,
  pgTable,
  timestamp,
  varchar,
  text,
  boolean,
  serial,
  integer,
  numeric,
} from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// Session storage table.
export const sessions = pgTable(
  "sessions",
  {
    sid: varchar("sid").primaryKey(),
    sess: jsonb("sess").notNull(),
    expire: timestamp("expire").notNull(),
  },
  (table) => [index("IDX_session_expire").on(table.expire)],
);

// User storage table matching existing database structure
export const users = pgTable("users", {
  id: serial("id").primaryKey(), // Existing database uses serial ID
  username: varchar("username", { length: 100 }).notNull(),
  email: varchar("email", { length: 255 }).unique().notNull(),
  password: varchar("password", { length: 255 }).notNull(),
  role: varchar("role", { length: 20 }).default("user"), // 'user' or 'owner'
  firstName: varchar("first_name", { length: 100 }),
  lastName: varchar("last_name", { length: 100 }),
  phone: varchar("phone", { length: 20 }),
  verified: boolean("verified").default(false),
  stripeCustomerId: varchar("stripe_customer_id", { length: 255 }),
  createdAt: timestamp("created_at").defaultNow(),

  // Customer fields
  customerLevel: varchar("customer_level", { length: 50 }),
  totalBookings: integer("total_bookings").default(0),
  totalSpent: numeric("total_spent").default("0"),
  loyaltyPoints: integer("loyalty_points").default(0),

  // Business fields for owners
  businessName: varchar("business_name", { length: 200 }),
  businessType: varchar("business_type", { length: 100 }),
  vatNumber: varchar("vat_number", { length: 50 }),
  website: varchar("website", { length: 255 }),
  instagram: varchar("instagram", { length: 100 }),
});

// Boats table schema that matches existing database structure exactly
export const boats = pgTable("boats", {
  id: serial("id").primaryKey(),
  hostId: integer("host_id").notNull(),
  name: text("name").notNull(),
  manufacturer: text("manufacturer"),
  type: text("type").notNull(),
  year: integer("year"),
  capacity: integer("max_persons"),
  length: numeric("length"),
  motorization: text("motorization"),
  licenseRequired: boolean("license_required"),
  skipperRequired: boolean("skipper_required"),
  location: text("port").notNull(),
  latitude: numeric("latitude"),
  longitude: numeric("longitude"),
  pricePerDay: numeric("price_per_day"),
  description: text("description"),
  images: text("images").array(),
  documentsRequired: text("documents_required"),
  active: boolean("active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  pickupTime: text("pickup_time"),
  returnTime: text("return_time"),
  dailyReturnRequired: boolean("daily_return_required"),
  cancellationPolicy: text("cancellation_policy"),
  refundMethod: text("refund_method"),
  cancellationRules: jsonb("cancellation_rules"),
});

// Bookings table
export const bookings = pgTable("bookings", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  customerId: varchar("customer_id").references(() => users.id).notNull(),
  boatId: varchar("boat_id").references(() => boats.id).notNull(),
  startDate: timestamp("start_date").notNull(),
  endDate: timestamp("end_date").notNull(),
  totalPrice: varchar("total_price", { length: 20 }),
  status: varchar("status", { length: 20 }).default("pending"), // pending, confirmed, cancelled
  specialRequests: text("special_requests"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Zod schemas for validation
export const insertUserSchema = createInsertSchema(users, {
  email: z.string().email("Email non valido"),
  password: z.string().min(6, "Password deve essere almeno 6 caratteri"),
  username: z.string().optional(), // Username is generated automatically from email
  firstName: z.string().min(1, "Nome richiesto").optional(),
  lastName: z.string().min(1, "Cognome richiesto").optional(),
  phone: z.string().optional(),
  role: z.enum(["user", "owner"]).default("user"),
  businessName: z.string().optional(),
  businessType: z.string().optional(),
  vatNumber: z.string().optional(),
  website: z.string().url().optional().or(z.literal("")),
  instagram: z.string().optional(),
}).omit({ id: true, createdAt: true });

// Schema specifico per registrazione owner
export const insertOwnerSchema = insertUserSchema.extend({
  role: z.literal("owner"),
  businessName: z.string().min(1, "Nome attività richiesto"),
  phone: z.string().min(1, "Telefono richiesto"),
  vatNumber: z.string().min(1, "P.IVA/Codice Fiscale richiesto"),
});

// Schema specifico per registrazione user
export const insertUserOnlySchema = insertUserSchema.extend({
  role: z.literal("user"),
});

export const loginSchema = z.object({
  email: z.string().email("Email non valido"),
  password: z.string().min(1, "Password richiesta"),
});

export const insertBoatSchema = createInsertSchema(boats, {
  name: z.string().min(1, "Nome richiesto"),
  type: z.string().min(1, "Tipo richiesto"),
  location: z.string().min(1, "Località richiesta"),
}).omit({ id: true, createdAt: true });

export const insertBookingSchema = createInsertSchema(bookings, {
  startDate: z.coerce.date(),
  endDate: z.coerce.date(),
}).omit({ id: true, createdAt: true, updatedAt: true });

// Legacy exports for compatibility
export const insertMooringSchema = insertBoatSchema;
export const insertMooringBookingSchema = insertBookingSchema;

export type InsertUser = z.infer<typeof insertUserSchema>;
export type InsertBoat = z.infer<typeof insertBoatSchema>;
export type InsertBooking = z.infer<typeof insertBookingSchema>;
export type User = typeof users.$inferSelect;
export type Boat = typeof boats.$inferSelect;
export type Booking = typeof bookings.$inferSelect;

